namespace Ets.Core.Domain.Services;

/// <summary>
///     Generates entity, aggregate, stream and message ids (ADR-0014).
/// </summary>
/// <remarks>
///     Ids are Guid v7 — time-ordered, so PostgreSQL B-tree locality stays good — and are generated by the
///     domain at the moment an entity is created. Injected so tests can control them.
/// </remarks>
public interface IIdGenerator
{
    Guid NewId();
}
